  await expect(secondInput).toHaveValue('World');

  // Additional visible checks after interactions
  await expect(button).toBeVisible();
  await expect(page.locator('cell').first()).toBeVisible();
  await expect(page.locator('customcell').first()).toBeVisible();
  await expect(page.locator('sheetnameprovider').first()).toBeVisible();
});

