test('new financial UI elements respond to input and sign toggle', async ({ page }) => {
  const cell = page.locator('cell').first();
  const signToggle = page.locator('view').filter({ hasText: '±' }).first();
  const financialText = page.locator('financialtext');
  const fields = page.locator('field');

  await expect(cell).toBeVisible();
  await expect(signToggle).toBeVisible();
  await expect(financialText).toBeVisible();
  await expect(financialText).toHaveText('');
  await expect(fields).toHaveCount(5);

  const amounts = ['10', '20', '30', '40', '50'];
  for (let i = 0; i < amounts.length; i++) {
    await fields.nth(i).pressSequentially(amounts[i]);
  }

  await signToggle.click();

  await expect(financialText).toBeVisible();
  await expect(financialText).not.toHaveText('');
});

