test('should configure condition and action UI elements', async ({ page }) => {
  // Navigate to the page (adjust if necessary; fixtures may already set base URL)
  await page.goto('/');

  // Verify that all new UI elements are visible initially
  const conditionsOp = page.getByTestId('conditions-op');
  const conditionList = page.getByTestId('condition-list');
  const actionSplitList = page.getByTestId('action-split-list');
  const actionList = page.getByTestId('action-list');
  const fieldSelect = page.getByTestId('field-select').first();
  const opSelect = page.getByTestId('op-select').first();
  const editorRow = page.getByTestId('editor-row').first();

  await expect(conditionsOp).toBeVisible();
  await expect(conditionList).toBeVisible();
  await expect(actionSplitList).toBeVisible();
  await expect(actionList).toBeVisible();
  await expect(fieldSelect).toBeVisible();
  await expect(opSelect).toBeVisible();
  await expect(editorRow).toBeVisible();

  // Exercise the conditions operator: change from "all" to "any"
  await conditionsOp.click();
  await page.keyboard.press('ArrowDown');
  await page.keyboard.press('Enter');

  // Assert visible outcome: operator now shows "any"
  await expect(conditionsOp).toContainText('any');

  // Exercise the field select: choose the first available field
  await fieldSelect.click();
  await page.keyboard.press('ArrowDown');
  await page.keyboard.press('Enter');
  const selectedField = await fieldSelect.textContent();
  expect(selectedField).toBeTruthy(); // Ensure a field was selected

  // Exercise the operator select: choose the first available operator
  await opSelect.click();
  await page.keyboard.press('ArrowDown');
  await page.keyboard.press('Enter');

  // Exercise the editor row: fill in a value
  const input = editorRow.locator('input').first();
  await input.fill('test value');

  // Assert visible outcome: condition list contains the selected field name
  await expect(conditionList).toContainText(selectedField!);
  // Assert visible outcome: the input holds the entered value
  await expect(input).toHaveValue('test value');
});

